#!/usr/bin/env bash
# step202 — email revisions: remove generic steps + extra buttons + "attached" note;
# product instructions only when present; single "Questions? WhatsApp us" button;
# footer line -> "Need help? Just message us on WhatsApp.". Re-send one test (dark
# email + Invoice + Receipt PDFs). pdfdocs unchanged.
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
TO="${1:-ishtiaqmails@gmail.com}"
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

cp -p lib/emails.js "lib/emails.js.bak-step202-$TS"
echo "backup: lib/emails.js.bak-step202-$TS"
restore(){ echo "!! restoring emails.js"; [ -f "lib/emails.js.bak-step202-$TS" ] && cp -p "lib/emails.js.bak-step202-$TS" lib/emails.js; }
trap 'restore' ERR

base64 -d > lib/emails.js <<'EEOF'

EEOF
node --check lib/emails.js || { echo 'EMAILS.JS SYNTAX FAIL'; restore; exit 2; }
grep -q 'Questions? WhatsApp us' lib/emails.js && grep -q 'Just message us on WhatsApp' lib/emails.js || { echo 'VERIFY FAILED'; restore; exit 3; }
grep -q 'How to get started' lib/emails.js && { echo 'VERIFY FAILED: old steps still present'; restore; exit 3; }
echo "verify ok: email revised"

trap - ERR
pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
  if [ "$code" = "200" ]; then ok=1; echo "health ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none})"; exit 4; }

SJS=$(mktemp /tmp/send202.XXXXXX.js)
base64 -d > "$SJS" <<'SEOF'

SEOF
NODE_PATH="$GSZ/node_modules" node "$SJS" "$TO"
echo "STEP202 DONE."
